docs=obj['documents']
pat=re.compile(r'\\bCPF\\s*#?\\s*[A-Z0-9]+(?:-[A-Z0-9]+)*', re.I)
formats={}
multiple=[]
for d in docs:
    lines=Path(d['doc_path']).read_text(errors='ignore').splitlines()
    found=[]
    for line in lines[:80]:
        for m in pat.finditer(line):
            found.append(m.group(0).strip())
    uniq=[]
    for f in found:
        if f not in uniq:
            uniq.append(f)
    if len(uniq) > 1:
        multiple.append((d['doc_name'], uniq[:5]))
    for f in uniq[:2]:
        formats[f]=formats.get(f,0)+1
